-- 客诉工单与服务质量分析系统 数据库初始化脚本
-- 生成时间 2026-11-01 20:49:08
-- 仅操作本项目库 new_050，不影响其他通道

DROP DATABASE IF EXISTS `new_050`;
CREATE DATABASE `new_050` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE `new_050`;

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;

DROP TABLE IF EXISTS `customer`;
CREATE TABLE `customer` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `customer_no` varchar(32) DEFAULT NULL COMMENT '客户编号',
  `customer_name` varchar(32) DEFAULT NULL COMMENT '客户姓名',
  `phone` varchar(20) DEFAULT NULL COMMENT '联系手机号',
  `customer_type` varchar(16) DEFAULT NULL COMMENT '客户类型 个人/企业/渠道客户',
  `region` varchar(48) DEFAULT NULL COMMENT '所属区域',
  `customer_level` varchar(16) DEFAULT NULL COMMENT '客户等级 普通/重要/VIP',
  `email` varchar(64) DEFAULT NULL COMMENT '电子邮箱',
  `address` varchar(160) DEFAULT NULL COMMENT '联系地址',
  `service_history` varchar(500) DEFAULT NULL COMMENT '服务历史摘要',
  `avatar` varchar(200) DEFAULT NULL COMMENT '客户头像路径',
  `user_id` bigint DEFAULT NULL COMMENT '关联登录账号',
  `status` varchar(16) DEFAULT NULL COMMENT '状态 正常/停用',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `version` int NOT NULL DEFAULT 1 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_customer_customer_no` (`customer_no`),
  KEY `idx_customer_phone` (`phone`),
  KEY `idx_customer_user_id` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='客户';

DROP TABLE IF EXISTS `service_object`;
CREATE TABLE `service_object` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `object_no` varchar(32) DEFAULT NULL COMMENT '对象编号',
  `object_name` varchar(80) DEFAULT NULL COMMENT '对象名称（产品/服务项目/门店）',
  `object_type` varchar(16) DEFAULT NULL COMMENT '对象类型 产品/服务项目/门店/订单',
  `cover_image` varchar(200) DEFAULT NULL COMMENT '对象封面图路径',
  `brand` varchar(48) DEFAULT NULL COMMENT '品牌',
  `model` varchar(64) DEFAULT NULL COMMENT '型号/规格',
  `store_name` varchar(64) DEFAULT NULL COMMENT '所属门店',
  `order_no` varchar(48) DEFAULT NULL COMMENT '关联订单号',
  `purchase_date` date DEFAULT NULL COMMENT '购买/开通日期',
  `warranty_end` date DEFAULT NULL COMMENT '保修或服务到期日',
  `status` varchar(16) DEFAULT NULL COMMENT '状态 在用/已过期/已停用',
  `remark` varchar(200) DEFAULT NULL COMMENT '备注',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `version` int NOT NULL DEFAULT 1 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_service_object_object_no` (`object_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='服务对象';

DROP TABLE IF EXISTS `complaint_category`;
CREATE TABLE `complaint_category` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `category_code` varchar(32) DEFAULT NULL COMMENT '分类编码',
  `category_name` varchar(64) DEFAULT NULL COMMENT '分类名称',
  `parent_id` bigint DEFAULT NULL COMMENT '上级分类 ID',
  `problem_type` varchar(32) DEFAULT NULL COMMENT '问题类型（创新因子）',
  `service_stage` varchar(32) DEFAULT NULL COMMENT '服务环节（创新因子）',
  `default_level` varchar(16) DEFAULT NULL COMMENT '建议级别 P1-P4',
  `response_hours` int DEFAULT NULL COMMENT '默认响应时限（小时）',
  `handle_hours` int DEFAULT NULL COMMENT '默认处理时限（小时）',
  `description` varchar(200) DEFAULT NULL COMMENT '分类说明',
  `status` varchar(16) DEFAULT NULL COMMENT '状态 启用/停用',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `version` int NOT NULL DEFAULT 1 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_complaint_category_category_code` (`category_code`),
  KEY `idx_complaint_category_parent_id` (`parent_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='投诉分类';

DROP TABLE IF EXISTS `severity_rule`;
CREATE TABLE `severity_rule` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `level_code` varchar(16) DEFAULT NULL COMMENT '级别编码 P1/P2/P3/P4',
  `level_name` varchar(32) DEFAULT NULL COMMENT '级别名称',
  `response_hours` int DEFAULT NULL COMMENT '响应时限（小时）',
  `handle_hours` int DEFAULT NULL COMMENT '处理时限（小时）',
  `escalate_hours` int DEFAULT NULL COMMENT '超过该小时数触发升级',
  `focus_flag` tinyint DEFAULT NULL COMMENT '是否进入重点关注 1 是 0 否',
  `color_class` varchar(16) DEFAULT NULL COMMENT '前端标签色 red/amber/blue/gray',
  `description` varchar(200) DEFAULT NULL COMMENT '级别说明',
  `status` varchar(16) DEFAULT NULL COMMENT '状态 启用/停用',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `version` int NOT NULL DEFAULT 1 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_severity_rule_level_code` (`level_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='级别规则';

DROP TABLE IF EXISTS `sla_rule`;
CREATE TABLE `sla_rule` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `rule_name` varchar(64) DEFAULT NULL COMMENT '规则名称',
  `category_id` bigint DEFAULT NULL COMMENT '适用分类',
  `level_code` varchar(16) DEFAULT NULL COMMENT '适用级别',
  `response_hours` int DEFAULT NULL COMMENT '响应时限（小时）',
  `handle_hours` int DEFAULT NULL COMMENT '处理时限（小时）',
  `warn_ratio` decimal(4,2) DEFAULT NULL COMMENT '预警阈值（剩余时限比例）',
  `overdue_upgrade` tinyint DEFAULT NULL COMMENT '超时自动升级 1 是 0 否',
  `effective_date` date DEFAULT NULL COMMENT '生效日期',
  `status` varchar(16) DEFAULT NULL COMMENT '状态 生效/停用',
  `remark` varchar(200) DEFAULT NULL COMMENT '备注',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `version` int NOT NULL DEFAULT 1 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_sla_rule_category_id` (`category_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='SLA 规则';

DROP TABLE IF EXISTS `complaint_ticket`;
CREATE TABLE `complaint_ticket` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `ticket_no` varchar(50) DEFAULT NULL COMMENT '客诉编号 TS+日期+序号',
  `customer_id` bigint DEFAULT NULL COMMENT '客户 ID',
  `customer_name` varchar(32) DEFAULT NULL COMMENT '客户姓名（冗余）',
  `phone` varchar(20) DEFAULT NULL COMMENT '联系手机号',
  `object_id` bigint DEFAULT NULL COMMENT '关联服务对象',
  `object_name` varchar(80) DEFAULT NULL COMMENT '关联对象名称（冗余）',
  `channel` varchar(16) DEFAULT NULL COMMENT '投诉渠道 电话/门店/邮件/在线/微信',
  `category_id` bigint DEFAULT NULL COMMENT '问题分类',
  `category_name` varchar(64) DEFAULT NULL COMMENT '分类名称（冗余）',
  `problem_type` varchar(32) DEFAULT NULL COMMENT '问题类型',
  `service_stage` varchar(32) DEFAULT NULL COMMENT '服务环节',
  `level_code` varchar(16) DEFAULT NULL COMMENT '严重等级 P1-P4',
  `title` varchar(120) DEFAULT NULL COMMENT '投诉主题',
  `content` varchar(1000) DEFAULT NULL COMMENT '投诉内容',
  `demand` varchar(100) DEFAULT NULL COMMENT '客户诉求',
  `occur_time` datetime DEFAULT NULL COMMENT '发生时间',
  `occur_place` varchar(120) DEFAULT NULL COMMENT '发生地点',
  `dept_id` bigint DEFAULT NULL COMMENT '责任部门',
  `dept_name` varchar(64) DEFAULT NULL COMMENT '责任部门名称',
  `status` varchar(24) DEFAULT NULL COMMENT '工单状态（主流程）',
  `current_handler_id` bigint DEFAULT NULL COMMENT '当前责任人',
  `current_handler_name` varchar(32) DEFAULT NULL COMMENT '当前责任人姓名',
  `accept_time` datetime DEFAULT NULL COMMENT '受理时间',
  `response_deadline` datetime DEFAULT NULL COMMENT '响应截止时间',
  `deadline_time` datetime DEFAULT NULL COMMENT '处理截止时间',
  `finish_time` datetime DEFAULT NULL COMMENT '处理完成时间',
  `confirm_time` datetime DEFAULT NULL COMMENT '客户确认时间',
  `archive_time` datetime DEFAULT NULL COMMENT '归档时间',
  `overdue_flag` tinyint DEFAULT NULL COMMENT '是否超时 1 是 0 否',
  `invalid_flag` tinyint DEFAULT NULL COMMENT '是否无效工单 1 是 0 否',
  `duplicate_flag` tinyint DEFAULT NULL COMMENT '是否重复投诉 1 是 0 否',
  `main_ticket_id` bigint DEFAULT NULL COMMENT '重复时关联的主工单 ID',
  `source` varchar(16) DEFAULT NULL COMMENT '来源 客服代录/客户自助',
  `cover_image` varchar(200) DEFAULT NULL COMMENT '投诉封面证据图路径',
  `reason_tags` varchar(200) DEFAULT NULL COMMENT '原因标签（创新因子，逗号分隔）',
  `product_tag` varchar(64) DEFAULT NULL COMMENT '关联产品标签（创新因子）',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `version` int NOT NULL DEFAULT 1 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_complaint_ticket_customer_id` (`customer_id`),
  KEY `idx_complaint_ticket_object_id` (`object_id`),
  KEY `idx_complaint_ticket_category_id` (`category_id`),
  KEY `idx_complaint_ticket_level_code` (`level_code`),
  KEY `idx_complaint_ticket_dept_id` (`dept_id`),
  KEY `idx_complaint_ticket_status` (`status`),
  KEY `idx_complaint_ticket_overdue_flag` (`overdue_flag`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='客户投诉主档';

DROP TABLE IF EXISTS `complaint_ticket_order`;
CREATE TABLE `complaint_ticket_order` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `order_no` varchar(50) DEFAULT NULL COMMENT '工单编号 WO+日期+序号',
  `ticket_id` bigint DEFAULT NULL COMMENT '所属投诉主档',
  `ticket_no` varchar(50) DEFAULT NULL COMMENT '客诉编号（冗余）',
  `node_name` varchar(32) DEFAULT NULL COMMENT '当前节点名称',
  `status` varchar(24) DEFAULT NULL COMMENT '工单状态',
  `handler_id` bigint DEFAULT NULL COMMENT '处理人 ID',
  `handler_name` varchar(32) DEFAULT NULL COMMENT '处理人姓名',
  `dept_id` bigint DEFAULT NULL COMMENT '责任部门',
  `dept_name` varchar(64) DEFAULT NULL COMMENT '责任部门名称',
  `priority` varchar(16) DEFAULT NULL COMMENT '优先级 高/中/低',
  `dispatch_time` datetime DEFAULT NULL COMMENT '分派时间',
  `accept_time` datetime DEFAULT NULL COMMENT '接单时间',
  `plan_finish_time` datetime DEFAULT NULL COMMENT '计划完成时间',
  `actual_finish_time` datetime DEFAULT NULL COMMENT '实际完成时间',
  `deadline_time` datetime DEFAULT NULL COMMENT '处理截止时间',
  `solution` varchar(1000) DEFAULT NULL COMMENT '解决方案',
  `result` varchar(1000) DEFAULT NULL COMMENT '处理结果',
  `return_reason` varchar(300) DEFAULT NULL COMMENT '退回原因',
  `overdue_flag` tinyint DEFAULT NULL COMMENT '是否超时 1 是 0 否',
  `coop_flag` tinyint DEFAULT NULL COMMENT '是否含跨部门协办 1 是 0 否',
  `close_time` datetime DEFAULT NULL COMMENT '工单关闭时间',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `version` int NOT NULL DEFAULT 1 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_complaint_ticket_order_order_no` (`order_no`),
  KEY `idx_complaint_ticket_order_ticket_id` (`ticket_id`),
  KEY `idx_complaint_ticket_order_status` (`status`),
  KEY `idx_complaint_ticket_order_handler_id` (`handler_id`),
  KEY `idx_complaint_ticket_order_dept_id` (`dept_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='客诉处理工单';

DROP TABLE IF EXISTS `complaint_ticket_record`;
CREATE TABLE `complaint_ticket_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `ticket_id` bigint DEFAULT NULL COMMENT '投诉主档 ID',
  `order_id` bigint DEFAULT NULL COMMENT '工单 ID',
  `record_type` varchar(24) DEFAULT NULL COMMENT '事件类型 创建/分派/接单/退回/处理/审核/确认/回访/归档/重开/升级',
  `from_status` varchar(24) DEFAULT NULL COMMENT '变更前状态',
  `to_status` varchar(24) DEFAULT NULL COMMENT '变更后状态',
  `content` varchar(1000) DEFAULT NULL COMMENT '记录内容',
  `operator_id` bigint DEFAULT NULL COMMENT '操作人 ID',
  `operator_name` varchar(32) DEFAULT NULL COMMENT '操作人姓名',
  `internal_flag` tinyint DEFAULT NULL COMMENT '是否仅内部可见 1 是 0 否',
  `operate_time` datetime DEFAULT NULL COMMENT '操作时间',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `version` int NOT NULL DEFAULT 1 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_complaint_ticket_record_ticket_id` (`ticket_id`),
  KEY `idx_complaint_ticket_record_order_id` (`order_id`),
  KEY `idx_complaint_ticket_record_operate_time` (`operate_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='投诉过程记录';

DROP TABLE IF EXISTS `complaint_ticket_attachment`;
CREATE TABLE `complaint_ticket_attachment` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `ticket_id` bigint DEFAULT NULL COMMENT '投诉主档 ID',
  `order_id` bigint DEFAULT NULL COMMENT '工单 ID',
  `file_name` varchar(200) DEFAULT NULL COMMENT '原始文件名',
  `file_path` varchar(300) DEFAULT NULL COMMENT '相对路径 /uploads/...',
  `file_size` bigint DEFAULT NULL COMMENT '文件大小（字节）',
  `file_type` varchar(64) DEFAULT NULL COMMENT 'MIME 类型',
  `biz_type` varchar(24) DEFAULT NULL COMMENT '用途 客户证据/处理凭证/整改凭证',
  `uploader_id` bigint DEFAULT NULL COMMENT '上传人',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `version` int NOT NULL DEFAULT 1 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_complaint_ticket_attachment_ticket_id` (`ticket_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='投诉附件';

DROP TABLE IF EXISTS `complaint_ticket_rule`;
CREATE TABLE `complaint_ticket_rule` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `rule_name` varchar(64) DEFAULT NULL COMMENT '规则名称',
  `rule_version` varchar(16) DEFAULT NULL COMMENT '规则版本 v1/v2/v3',
  `w_product` int DEFAULT NULL COMMENT '关联产品权重',
  `w_stage` int DEFAULT NULL COMMENT '服务环节权重',
  `w_problem` int DEFAULT NULL COMMENT '问题类型权重',
  `w_reason` int DEFAULT NULL COMMENT '原因标签权重',
  `w_dept` int DEFAULT NULL COMMENT '责任部门权重',
  `w_freq` int DEFAULT NULL COMMENT '近30天次数权重',
  `high_threshold` int DEFAULT NULL COMMENT '高相似阈值',
  `mid_threshold` int DEFAULT NULL COMMENT '中相似阈值',
  `window_days` int DEFAULT NULL COMMENT '统计窗口（天）',
  `effective_time` datetime DEFAULT NULL COMMENT '生效时间',
  `status` varchar(16) DEFAULT NULL COMMENT '状态 启用/停用',
  `operator_name` varchar(32) DEFAULT NULL COMMENT '配置人',
  `remark` varchar(200) DEFAULT NULL COMMENT '变更说明',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `version` int NOT NULL DEFAULT 1 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='共性问题聚类规则';

DROP TABLE IF EXISTS `complaint_ticket_score`;
CREATE TABLE `complaint_ticket_score` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `ticket_id` bigint DEFAULT NULL COMMENT '投诉主档 ID',
  `ticket_no` varchar(50) DEFAULT NULL COMMENT '客诉编号',
  `cluster_name` varchar(80) DEFAULT NULL COMMENT '聚类主题',
  `rule_version` varchar(16) DEFAULT NULL COMMENT '计算所用规则版本',
  `s_product` int DEFAULT NULL COMMENT '关联产品得分',
  `s_stage` int DEFAULT NULL COMMENT '服务环节得分',
  `s_problem` int DEFAULT NULL COMMENT '问题类型得分',
  `s_reason` int DEFAULT NULL COMMENT '原因标签得分',
  `s_dept` int DEFAULT NULL COMMENT '责任部门得分',
  `s_freq` int DEFAULT NULL COMMENT '近30天次数得分',
  `similarity` decimal(5,2) DEFAULT NULL COMMENT '综合相似度',
  `level` varchar(16) DEFAULT NULL COMMENT '结果等级 HIGH/MID/LOW',
  `input_snapshot` varchar(1000) DEFAULT NULL COMMENT '输入快照（可追溯）',
  `reasons` varchar(500) DEFAULT NULL COMMENT '主要影响因素',
  `unmet` varchar(300) DEFAULT NULL COMMENT '未满足条件',
  `improve` varchar(300) DEFAULT NULL COMMENT '可改进项',
  `calc_time` datetime DEFAULT NULL COMMENT '计算时间',
  `manual_level` varchar(16) DEFAULT NULL COMMENT '人工调整等级',
  `manual_reason` varchar(300) DEFAULT NULL COMMENT '人工调整原因',
  `manual_by` varchar(32) DEFAULT NULL COMMENT '调整人',
  `manual_time` datetime DEFAULT NULL COMMENT '调整时间',
  `adopt_flag` tinyint DEFAULT NULL COMMENT '是否已转整改 1 是 0 否',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `version` int NOT NULL DEFAULT 1 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_complaint_ticket_score_ticket_id` (`ticket_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='共性问题聚类计算结果';

DROP TABLE IF EXISTS `dispatch_record`;
CREATE TABLE `dispatch_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `ticket_id` bigint DEFAULT NULL COMMENT '投诉主档 ID',
  `order_id` bigint DEFAULT NULL COMMENT '工单 ID',
  `dispatch_type` varchar(16) DEFAULT NULL COMMENT '类型 首次分派/转派/升级转派',
  `from_dept_id` bigint DEFAULT NULL COMMENT '原责任部门',
  `to_dept_id` bigint DEFAULT NULL COMMENT '新责任部门',
  `to_dept_name` varchar(64) DEFAULT NULL COMMENT '新责任部门名称',
  `handler_id` bigint DEFAULT NULL COMMENT '指定处理人',
  `handler_name` varchar(32) DEFAULT NULL COMMENT '处理人姓名',
  `reason` varchar(300) DEFAULT NULL COMMENT '分派/转派原因',
  `operator_id` bigint DEFAULT NULL COMMENT '操作人',
  `operator_name` varchar(32) DEFAULT NULL COMMENT '操作人姓名',
  `dispatch_time` datetime DEFAULT NULL COMMENT '分派时间',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `version` int NOT NULL DEFAULT 1 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_dispatch_record_ticket_id` (`ticket_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='分派记录';

DROP TABLE IF EXISTS `coop_task`;
CREATE TABLE `coop_task` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `ticket_id` bigint DEFAULT NULL COMMENT '投诉主档 ID',
  `order_id` bigint DEFAULT NULL COMMENT '主工单 ID',
  `dept_id` bigint DEFAULT NULL COMMENT '协办部门',
  `dept_name` varchar(64) DEFAULT NULL COMMENT '协办部门名称',
  `handler_id` bigint DEFAULT NULL COMMENT '协办责任人',
  `handler_name` varchar(32) DEFAULT NULL COMMENT '协办人姓名',
  `task_content` varchar(300) DEFAULT NULL COMMENT '协办任务内容',
  `deadline_time` datetime DEFAULT NULL COMMENT '协办截止时间',
  `status` varchar(16) DEFAULT NULL COMMENT '状态 待接单/处理中/已完成/已退回',
  `result` varchar(500) DEFAULT NULL COMMENT '协办结果',
  `finish_time` datetime DEFAULT NULL COMMENT '完成时间',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `version` int NOT NULL DEFAULT 1 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_coop_task_ticket_id` (`ticket_id`),
  KEY `idx_coop_task_dept_id` (`dept_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='协办任务';

DROP TABLE IF EXISTS `handle_record`;
CREATE TABLE `handle_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `ticket_id` bigint DEFAULT NULL COMMENT '投诉主档 ID',
  `order_id` bigint DEFAULT NULL COMMENT '工单 ID',
  `step_no` int DEFAULT NULL COMMENT '处理步骤序号',
  `content` varchar(1000) DEFAULT NULL COMMENT '调查情况与内部意见',
  `solution` varchar(1000) DEFAULT NULL COMMENT '解决方案',
  `attach_path` varchar(300) DEFAULT NULL COMMENT '处理附件路径',
  `plan_finish_time` datetime DEFAULT NULL COMMENT '计划完成时间',
  `operator_id` bigint DEFAULT NULL COMMENT '记录人',
  `operator_name` varchar(32) DEFAULT NULL COMMENT '记录人姓名',
  `handle_time` datetime DEFAULT NULL COMMENT '记录时间',
  `internal_flag` tinyint DEFAULT NULL COMMENT '是否内部可见 1 是 0 否',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `version` int NOT NULL DEFAULT 1 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_handle_record_ticket_id` (`ticket_id`),
  KEY `idx_handle_record_order_id` (`order_id`),
  KEY `idx_handle_record_handle_time` (`handle_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='处理记录';

DROP TABLE IF EXISTS `comm_record`;
CREATE TABLE `comm_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `ticket_id` bigint DEFAULT NULL COMMENT '投诉主档 ID',
  `order_id` bigint DEFAULT NULL COMMENT '工单 ID',
  `comm_type` varchar(16) DEFAULT NULL COMMENT '沟通方式 电话/在线消息/现场/邮件',
  `comm_time` datetime DEFAULT NULL COMMENT '沟通时间',
  `summary` varchar(500) DEFAULT NULL COMMENT '沟通摘要',
  `customer_feedback` varchar(300) DEFAULT NULL COMMENT '客户反馈',
  `operator_id` bigint DEFAULT NULL COMMENT '沟通人',
  `operator_name` varchar(32) DEFAULT NULL COMMENT '沟通人姓名',
  `visible_flag` tinyint DEFAULT NULL COMMENT '是否客户可见 1 是 0 否',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `version` int NOT NULL DEFAULT 1 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_comm_record_ticket_id` (`ticket_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='客户沟通记录';

DROP TABLE IF EXISTS `warning_record`;
CREATE TABLE `warning_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `ticket_id` bigint DEFAULT NULL COMMENT '投诉主档 ID',
  `order_no` varchar(50) DEFAULT NULL COMMENT '工单编号',
  `warn_type` varchar(24) DEFAULT NULL COMMENT '类型 即将超时/响应超时/处理超时/长期未更新',
  `warn_level` varchar(16) DEFAULT NULL COMMENT '预警级别 提醒/严重',
  `warn_time` datetime DEFAULT NULL COMMENT '预警时间',
  `deadline_time` datetime DEFAULT NULL COMMENT '对应截止时间',
  `gap_minutes` int DEFAULT NULL COMMENT '距截止的分钟数（负数为已超时）',
  `status` varchar(16) DEFAULT NULL COMMENT '状态 未处理/已处理/已忽略',
  `handler_id` bigint DEFAULT NULL COMMENT '处理人',
  `handle_time` datetime DEFAULT NULL COMMENT '处理时间',
  `handle_note` varchar(300) DEFAULT NULL COMMENT '处理说明',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `version` int NOT NULL DEFAULT 1 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_warning_record_ticket_id` (`ticket_id`),
  KEY `idx_warning_record_warn_time` (`warn_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='时限预警记录';

DROP TABLE IF EXISTS `urge_record`;
CREATE TABLE `urge_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `ticket_id` bigint DEFAULT NULL COMMENT '投诉主档 ID',
  `order_id` bigint DEFAULT NULL COMMENT '工单 ID',
  `urge_type` varchar(16) DEFAULT NULL COMMENT '类型 客服催办/组长催办/系统自动',
  `urge_content` varchar(300) DEFAULT NULL COMMENT '催办内容',
  `urge_by` varchar(32) DEFAULT NULL COMMENT '催办人',
  `urge_to` varchar(32) DEFAULT NULL COMMENT '被催办人',
  `urge_time` datetime DEFAULT NULL COMMENT '催办时间',
  `feedback` varchar(300) DEFAULT NULL COMMENT '反馈内容',
  `feedback_time` datetime DEFAULT NULL COMMENT '反馈时间',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `version` int NOT NULL DEFAULT 1 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_urge_record_ticket_id` (`ticket_id`),
  KEY `idx_urge_record_urge_time` (`urge_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='催办记录';

DROP TABLE IF EXISTS `escalate_record`;
CREATE TABLE `escalate_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `ticket_id` bigint DEFAULT NULL COMMENT '投诉主档 ID',
  `order_id` bigint DEFAULT NULL COMMENT '工单 ID',
  `from_level` varchar(16) DEFAULT NULL COMMENT '原等级',
  `to_level` varchar(16) DEFAULT NULL COMMENT '升级后等级',
  `escalate_type` varchar(16) DEFAULT NULL COMMENT '类型 超时升级/人工升级/重大投诉',
  `reason` varchar(300) DEFAULT NULL COMMENT '升级原因',
  `escalate_by` varchar(32) DEFAULT NULL COMMENT '发起人',
  `escalate_to` varchar(32) DEFAULT NULL COMMENT '升级接收人',
  `escalate_time` datetime DEFAULT NULL COMMENT '升级时间',
  `confirm_time` datetime DEFAULT NULL COMMENT '确认时间',
  `status` varchar(16) DEFAULT NULL COMMENT '状态 待确认/已确认',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `version` int NOT NULL DEFAULT 1 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_escalate_record_ticket_id` (`ticket_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='升级记录';

DROP TABLE IF EXISTS `delay_apply`;
CREATE TABLE `delay_apply` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `apply_no` varchar(50) DEFAULT NULL COMMENT '申请单号 DL+日期+序号',
  `ticket_id` bigint DEFAULT NULL COMMENT '投诉主档 ID',
  `order_id` bigint DEFAULT NULL COMMENT '工单 ID',
  `old_deadline` datetime DEFAULT NULL COMMENT '原截止时间',
  `new_deadline` datetime DEFAULT NULL COMMENT '申请新截止时间',
  `delay_hours` int DEFAULT NULL COMMENT '延长小时数',
  `reason` varchar(300) DEFAULT NULL COMMENT '延时原因（不少于 5 字）',
  `applicant_id` bigint DEFAULT NULL COMMENT '申请人',
  `applicant_name` varchar(32) DEFAULT NULL COMMENT '申请人姓名',
  `apply_time` datetime DEFAULT NULL COMMENT '申请时间',
  `status` varchar(16) DEFAULT NULL COMMENT '状态 待审批/已通过/已驳回',
  `approver_id` bigint DEFAULT NULL COMMENT '审批人',
  `approver_name` varchar(32) DEFAULT NULL COMMENT '审批人姓名',
  `approve_time` datetime DEFAULT NULL COMMENT '审批时间',
  `approve_note` varchar(300) DEFAULT NULL COMMENT '审批意见',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `version` int NOT NULL DEFAULT 1 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_delay_apply_ticket_id` (`ticket_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='延时申请';

DROP TABLE IF EXISTS `review_record`;
CREATE TABLE `review_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `review_no` varchar(50) DEFAULT NULL COMMENT '审核单号 RV+序号',
  `ticket_id` bigint DEFAULT NULL COMMENT '投诉主档 ID',
  `order_id` bigint DEFAULT NULL COMMENT '工单 ID',
  `review_result` varchar(16) DEFAULT NULL COMMENT '审核结果 通过/驳回',
  `plan_score` int DEFAULT NULL COMMENT '方案完整度评分 0-100',
  `evidence_flag` tinyint DEFAULT NULL COMMENT '证据是否齐全 1 是 0 否',
  `duty_check` varchar(200) DEFAULT NULL COMMENT '责任认定核查结论',
  `opinion` varchar(300) DEFAULT NULL COMMENT '审核意见',
  `reviewer_id` bigint DEFAULT NULL COMMENT '审核人',
  `reviewer_name` varchar(32) DEFAULT NULL COMMENT '审核人姓名',
  `review_time` datetime DEFAULT NULL COMMENT '审核时间',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `version` int NOT NULL DEFAULT 1 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_review_record_ticket_id` (`ticket_id`),
  KEY `idx_review_record_review_time` (`review_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='结果审核记录';

DROP TABLE IF EXISTS `customer_confirm`;
CREATE TABLE `customer_confirm` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `ticket_id` bigint DEFAULT NULL COMMENT '投诉主档 ID',
  `order_id` bigint DEFAULT NULL COMMENT '工单 ID',
  `confirm_result` varchar(24) DEFAULT NULL COMMENT '结果 接受/提出异议/超期未确认',
  `opinion` varchar(300) DEFAULT NULL COMMENT '客户意见',
  `confirm_time` datetime DEFAULT NULL COMMENT '确认时间',
  `deadline_time` datetime DEFAULT NULL COMMENT '确认截止时间',
  `auto_flag` tinyint DEFAULT NULL COMMENT '是否系统自动判定 1 是 0 否',
  `remind_count` int DEFAULT NULL COMMENT '提醒次数',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `version` int NOT NULL DEFAULT 1 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_customer_confirm_ticket_id` (`ticket_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='客户确认记录';

DROP TABLE IF EXISTS `reopen_record`;
CREATE TABLE `reopen_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `reopen_no` varchar(50) DEFAULT NULL COMMENT '重开单号 RO+序号',
  `ticket_id` bigint DEFAULT NULL COMMENT '投诉主档 ID',
  `source_order_id` bigint DEFAULT NULL COMMENT '原工单 ID',
  `new_order_id` bigint DEFAULT NULL COMMENT '新工单 ID',
  `reopen_reason` varchar(300) DEFAULT NULL COMMENT '重开原因（不少于 5 字）',
  `reopen_count` int DEFAULT NULL COMMENT '第几次重开',
  `applicant` varchar(32) DEFAULT NULL COMMENT '申请人',
  `apply_time` datetime DEFAULT NULL COMMENT '申请时间',
  `status` varchar(16) DEFAULT NULL COMMENT '状态 待受理/已受理/已驳回',
  `handler_id` bigint DEFAULT NULL COMMENT '受理人',
  `handle_time` datetime DEFAULT NULL COMMENT '受理时间',
  `handle_note` varchar(300) DEFAULT NULL COMMENT '受理说明',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `version` int NOT NULL DEFAULT 1 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_reopen_record_ticket_id` (`ticket_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='重开记录';

DROP TABLE IF EXISTS `revisit_record`;
CREATE TABLE `revisit_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `revisit_no` varchar(50) DEFAULT NULL COMMENT '回访单号 VZ+序号',
  `ticket_id` bigint DEFAULT NULL COMMENT '投诉主档 ID',
  `order_id` bigint DEFAULT NULL COMMENT '工单 ID',
  `revisit_type` varchar(16) DEFAULT NULL COMMENT '回访方式 电话/在线/现场',
  `solved_flag` tinyint DEFAULT NULL COMMENT '问题是否解决 1 是 0 否',
  `satisfaction` int DEFAULT NULL COMMENT '满意度 1-5',
  `opinion` varchar(300) DEFAULT NULL COMMENT '客户意见',
  `next_action` varchar(200) DEFAULT NULL COMMENT '后续行动',
  `revisitor_id` bigint DEFAULT NULL COMMENT '回访人',
  `revisitor_name` varchar(32) DEFAULT NULL COMMENT '回访人姓名',
  `revisit_time` datetime DEFAULT NULL COMMENT '回访时间',
  `duration_min` int DEFAULT NULL COMMENT '通话时长（分钟）',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `version` int NOT NULL DEFAULT 1 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_revisit_record_ticket_id` (`ticket_id`),
  KEY `idx_revisit_record_revisit_time` (`revisit_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='回访记录';

DROP TABLE IF EXISTS `evaluate_record`;
CREATE TABLE `evaluate_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `ticket_id` bigint DEFAULT NULL COMMENT '投诉主档 ID',
  `order_id` bigint DEFAULT NULL COMMENT '工单 ID',
  `score` int DEFAULT NULL COMMENT '综合评分 1-5',
  `attitude_score` int DEFAULT NULL COMMENT '服务态度评分 1-5',
  `speed_score` int DEFAULT NULL COMMENT '处理速度评分 1-5',
  `quality_score` int DEFAULT NULL COMMENT '处理质量评分 1-5',
  `content` varchar(300) DEFAULT NULL COMMENT '评价内容',
  `anonymous_flag` tinyint DEFAULT NULL COMMENT '是否匿名 1 是 0 否',
  `customer_id` bigint DEFAULT NULL COMMENT '客户 ID',
  `evaluate_time` datetime DEFAULT NULL COMMENT '评价时间',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `version` int NOT NULL DEFAULT 1 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_evaluate_record_ticket_id` (`ticket_id`),
  KEY `idx_evaluate_record_evaluate_time` (`evaluate_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='客户评价';

DROP TABLE IF EXISTS `rectify_task`;
CREATE TABLE `rectify_task` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `task_no` varchar(50) DEFAULT NULL COMMENT '整改单号 RC+日期+序号',
  `title` varchar(120) DEFAULT NULL COMMENT '整改主题',
  `cluster_name` varchar(80) DEFAULT NULL COMMENT '来源聚类主题',
  `dept_id` bigint DEFAULT NULL COMMENT '责任部门',
  `dept_name` varchar(64) DEFAULT NULL COMMENT '责任部门名称',
  `measure` varchar(1000) DEFAULT NULL COMMENT '整改措施',
  `deadline` date DEFAULT NULL COMMENT '整改期限',
  `owner_id` bigint DEFAULT NULL COMMENT '整改负责人',
  `owner_name` varchar(32) DEFAULT NULL COMMENT '负责人姓名',
  `accept_id` bigint DEFAULT NULL COMMENT '验收人',
  `accept_name` varchar(32) DEFAULT NULL COMMENT '验收人姓名',
  `status` varchar(16) DEFAULT NULL COMMENT '状态 待下发/整改中/待验收/已验收/已关闭',
  `source_tickets` varchar(200) DEFAULT NULL COMMENT '引发整改的客诉编号（逗号分隔）',
  `finish_time` datetime DEFAULT NULL COMMENT '完成时间',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `version` int NOT NULL DEFAULT 1 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_rectify_task_dept_id` (`dept_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='整改任务';

DROP TABLE IF EXISTS `rectify_accept`;
CREATE TABLE `rectify_accept` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `task_id` bigint DEFAULT NULL COMMENT '整改任务 ID',
  `accept_result` varchar(16) DEFAULT NULL COMMENT '验收结果 通过/不通过',
  `evidence_path` varchar(300) DEFAULT NULL COMMENT '整改凭证图片路径',
  `opinion` varchar(300) DEFAULT NULL COMMENT '验收意见',
  `acceptor_id` bigint DEFAULT NULL COMMENT '验收人',
  `acceptor_name` varchar(32) DEFAULT NULL COMMENT '验收人姓名',
  `accept_time` datetime DEFAULT NULL COMMENT '验收时间',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `version` int NOT NULL DEFAULT 1 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_rectify_accept_task_id` (`task_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='整改验收记录';

DROP TABLE IF EXISTS `knowledge_item`;
CREATE TABLE `knowledge_item` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `item_no` varchar(50) DEFAULT NULL COMMENT '条目编号 KB+序号',
  `title` varchar(120) DEFAULT NULL COMMENT '标题',
  `category_name` varchar(64) DEFAULT NULL COMMENT '分类',
  `keywords` varchar(200) DEFAULT NULL COMMENT '关键词（逗号分隔）',
  `content` varchar(2000) DEFAULT NULL COMMENT '解决方案正文',
  `source_ticket_id` bigint DEFAULT NULL COMMENT '来源投诉',
  `author_id` bigint DEFAULT NULL COMMENT '撰写人',
  `author_name` varchar(32) DEFAULT NULL COMMENT '撰写人姓名',
  `view_count` int DEFAULT NULL COMMENT '查看次数',
  `status` varchar(16) DEFAULT NULL COMMENT '状态 启用/停用',
  `publish_time` datetime DEFAULT NULL COMMENT '发布时间',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `version` int NOT NULL DEFAULT 1 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='知识库条目';

DROP TABLE IF EXISTS `sys_user`;
CREATE TABLE `sys_user` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `username` varchar(64) DEFAULT NULL COMMENT '登录账号',
  `password` varchar(100) DEFAULT NULL COMMENT 'BCrypt 密码',
  `real_name` varchar(32) DEFAULT NULL COMMENT '姓名',
  `phone` varchar(20) DEFAULT NULL COMMENT '手机号',
  `avatar` varchar(200) DEFAULT NULL COMMENT '头像路径',
  `role_id` bigint DEFAULT NULL COMMENT '角色 ID',
  `org_id` bigint DEFAULT NULL COMMENT '所属部门',
  `data_scope` varchar(24) DEFAULT NULL COMMENT '数据范围 ALL/ORG/SELF',
  `status` tinyint DEFAULT NULL COMMENT '状态 1 正常 0 停用',
  `fail_count` int DEFAULT NULL COMMENT '连续登录失败次数',
  `lock_time` datetime DEFAULT NULL COMMENT '锁定到期时间',
  `last_login_time` datetime DEFAULT NULL COMMENT '最后登录时间',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sys_user_username` (`username`),
  KEY `idx_sys_user_role_id` (`role_id`),
  KEY `idx_sys_user_org_id` (`org_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='用户';

DROP TABLE IF EXISTS `sys_role`;
CREATE TABLE `sys_role` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `role_code` varchar(32) DEFAULT NULL COMMENT '角色编码',
  `role_name` varchar(64) DEFAULT NULL COMMENT '角色名称',
  `data_scope` varchar(24) DEFAULT NULL COMMENT '数据范围 ALL/ORG/SELF',
  `remark` varchar(200) DEFAULT NULL COMMENT '备注',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sys_role_role_code` (`role_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='角色';

DROP TABLE IF EXISTS `sys_menu`;
CREATE TABLE `sys_menu` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `parent_id` bigint DEFAULT NULL COMMENT '父菜单 ID',
  `menu_name` varchar(64) DEFAULT NULL COMMENT '菜单名称',
  `path` varchar(120) DEFAULT NULL COMMENT '前端路由',
  `perm` varchar(120) DEFAULT NULL COMMENT '权限标识',
  `icon` varchar(64) DEFAULT NULL COMMENT '图标名',
  `sort_no` int DEFAULT NULL COMMENT '排序',
  `visible` tinyint DEFAULT NULL COMMENT '是否显示 1 是 0 否',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_sys_menu_parent_id` (`parent_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='菜单';

DROP TABLE IF EXISTS `sys_role_menu`;
CREATE TABLE `sys_role_menu` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `role_id` bigint DEFAULT NULL COMMENT '角色 ID',
  `menu_id` bigint DEFAULT NULL COMMENT '菜单 ID',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_sys_role_menu_role_id` (`role_id`),
  KEY `idx_sys_role_menu_menu_id` (`menu_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='角色菜单';

DROP TABLE IF EXISTS `sys_org`;
CREATE TABLE `sys_org` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `org_name` varchar(64) DEFAULT NULL COMMENT '部门名称',
  `org_type` varchar(24) DEFAULT NULL COMMENT '类型 公司/中心/部门/门店',
  `parent_id` bigint DEFAULT NULL COMMENT '上级 ID',
  `contact` varchar(32) DEFAULT NULL COMMENT '负责人',
  `phone` varchar(20) DEFAULT NULL COMMENT '联系电话',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sys_org_org_name` (`org_name`),
  KEY `idx_sys_org_parent_id` (`parent_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='部门';

DROP TABLE IF EXISTS `sys_message`;
CREATE TABLE `sys_message` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `title` varchar(120) DEFAULT NULL COMMENT '标题',
  `content` varchar(500) DEFAULT NULL COMMENT '内容',
  `msg_type` varchar(24) DEFAULT NULL COMMENT '类型 待处理/待审核/时限预警/待验收/系统通知',
  `link_url` varchar(200) DEFAULT NULL COMMENT '详情跳转地址',
  `receiver_id` bigint DEFAULT NULL COMMENT '接收人',
  `is_read` tinyint DEFAULT NULL COMMENT '是否已读 1 是 0 否',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_sys_message_receiver_id` (`receiver_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='站内消息';

DROP TABLE IF EXISTS `sys_dict`;
CREATE TABLE `sys_dict` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `dict_type` varchar(48) DEFAULT NULL COMMENT '字典类型',
  `dict_label` varchar(64) DEFAULT NULL COMMENT '显示名',
  `dict_value` varchar(64) DEFAULT NULL COMMENT '值',
  `sort_no` int DEFAULT NULL COMMENT '排序',
  `status` tinyint DEFAULT NULL COMMENT '状态 1 启用 0 停用',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_sys_dict_dict_type` (`dict_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='字典';

DROP TABLE IF EXISTS `sys_file`;
CREATE TABLE `sys_file` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `file_name` varchar(200) DEFAULT NULL COMMENT '原始文件名',
  `file_path` varchar(300) DEFAULT NULL COMMENT '相对路径',
  `file_size` bigint DEFAULT NULL COMMENT '大小（字节）',
  `file_type` varchar(64) DEFAULT NULL COMMENT 'MIME 类型',
  `uploader_id` bigint DEFAULT NULL COMMENT '上传人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='文件';

DROP TABLE IF EXISTS `sys_log`;
CREATE TABLE `sys_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` bigint DEFAULT NULL COMMENT '操作人 ID',
  `user_name` varchar(32) DEFAULT NULL COMMENT '操作人',
  `module` varchar(48) DEFAULT NULL COMMENT '模块',
  `action` varchar(64) DEFAULT NULL COMMENT '动作',
  `method` varchar(120) DEFAULT NULL COMMENT '方法',
  `params` varchar(1000) DEFAULT NULL COMMENT '参数',
  `ip` varchar(48) DEFAULT NULL COMMENT 'IP',
  `status` tinyint DEFAULT NULL COMMENT '结果 1 成功 0 失败',
  `cost_ms` int DEFAULT NULL COMMENT '耗时（毫秒）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_sys_log_user_id` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='操作日志';

SET FOREIGN_KEY_CHECKS=1;

